6	)
7	
8	// poseShift 描述一次回环校正对轨迹施加的同一次刚体重定位：锚点落到目标
9	// 位置、朝向归一到 [-π,π)；从锚点到末帧的其余帧与锚点一起平移旋转，保留
10	// 各帧相对锚点的位置关系与朝向差。提交校正（Correct）与打开地图时的校正
11	// 记录几何核对（validateLoaded，见 persistence.go）共用这同一份规则与
12	// 运算次序，两处对“校正后位置与朝向”的理解因此始终一致。
13	type poseShift struct {
14		x, y       float64 // 目标位置，即锚点校正后位置
15		heading    float64 // 目标朝向归一到 [-π,π)，即锚点校正后朝向
16		anchorX    float64 // 锚点校正前位置
17		anchorY    float64
18		dHeading   float64 // 归一后的最短朝向差，即各帧叠加的旋转角
19		cosD, sinD float64 // 旋转角的余弦与正弦
20		identity   bool    // 只调方差的恒等校正：位置与朝向保持原值
21	}
22	
23	// newPoseShift 按提交目标与锚点校正前位姿构造重定位。目标朝向先归一，
24	// 旋转角取归一后的最短朝向差。目标位置与锚点原位置完全相同、目标朝向归
25	// 一后与原朝向等价（旋转角为 0）时是恒等校正：几何上没有任何平移或旋
26	// 转，校正前后位姿必须完全相同。恒等校正不能套用旋转平移公式——公式会
27	// 先求相对锚点的偏移，轨迹横跨 ±1e308 这类大坐标时该差值先溢出为
28	// ±Inf、再参与浮点运算退化为 NaN，使本应成功的校正被误判为数值异常；
29	// 恒等校正直接保留原位姿。
30	func newPoseShift(tgt CorrectionTarget, anchorBefore Pose) poseShift {
31		heading := normalizeAngle(tgt.Heading)
32		dHeading := normalizeAngle(heading - anchorBefore.Heading)
33		return poseShift{
34			x:        tgt.X,
35			y:        tgt.Y,
36			heading:  heading,
37			anchorX:  anchorBefore.X,
38			anchorY:  anchorBefore.Y,
39			dHeading: dHeading,
40			cosD:     math.Cos(dHeading),
41			sinD:     math.Sin(dHeading),
42			identity: dHeading == 0 && tgt.X == anchorBefore.X && tgt.Y == anchorBefore.Y,
43		}
44	}
45	
46	// apply 计算一帧校正后的位置与朝向：恒等校正原样保留校正前值；否则把校
47	// 正前相对锚点的偏移随锚点一起旋转平移，朝向叠加同一旋转角并归一到
48	// [-π,π)。帧时间与方差不属于几何规则，由调用方处理。
49	func (s poseShift) apply(before Pose) (x, y, heading float64) {
50		if s.identity {
51			return before.X, before.Y, before.Heading
52		}
53		dx := before.X - s.anchorX
54		dy := before.Y - s.anchorY
55		return s.x + s.cosD*dx - s.sinD*dy,
56			s.y + s.sinD*dx + s.cosD*dy,
57			normalizeAngle(before.Heading + s.dHeading)
58	}
59	
60	// Correct 提交一次已确认回环校正。
61	//
62	// req.ID 必须非空；req.Anchor 必须准确命中一个已导入帧的时间（不能是
63	// 初始位姿，也不借用历史查询得到的最近一帧）；目标位姿数值必须有限、
64	// 目标方差必须非负。命中后，锚点帧采用提交的位姿；从锚点到提交时末帧
65	// 的轨迹整体平移并旋转（保持这些帧在校正前彼此的相对位置与朝向，时间
66	// 不变，朝向归一到既有范围）；锚点之后每帧的方差等于目标方差加上锚点
67	// 之后至该帧的原运动方差累计值。更早的位姿不变。
68	//
69	// 受影响帧中的路标观测随新位姿改变地图位置；更早观测的地图位置不变。
70	// 同一路标仍按全部已接受观测、依原时间与同帧输入次序做增量平均并遵守
71	// 合并距离限制；观测次数不变。若校正后出现路标冲突，整次校正拒绝并说
72	// 明冲突帧时间与路标。输入或校正结果含非有限数值同样拒绝；观测转换到
73	// 地图坐标后溢出为 NaN/无穷时按数值异常拒绝，说明该观测所在帧的实际
74	// 时间、路标标识与出现编号，而不是误报为距离冲突。
75	//
76	// 同一标识以相同内容重复提交返回首次结果且不再修改数据；同一标识不同
77	// 内容明确拒绝。任何拒绝或保存失败都不改变轨迹、路标与既有校正记录。
78	// 旧文件缺少逐帧观测来源时，覆盖其历史范围的校正返回 RejectNoBasis。
79	func (m *Map) Correct(req Correction) (CorrectionRecord, error) {
80		m.mu.Lock()
81		defer m.mu.Unlock()
82		if m.closed {
83			return CorrectionRecord{}, ErrClosed
84		}
85		st := m.state
86	
87		// 已保存校正：相同内容直接返回首次记录；不同内容明确拒绝。
88		// 不做任何校验或状态变更，即使其后又提交过其他校正。
89		if hash, ok := st.corrIndex[req.ID]; ok {
90			if hash == canonicalCorrectionHash(req.Anchor, req.Target) {
91				return cloneRecord(st.correctionRecordByID(req.ID)), nil
92			}
93			return CorrectionRecord{}, &RejectError{Kind: RejectCorrectionMismatch, Landmark: req.ID, HasLandmark: true}
94		}
95	
96		if req.ID == "" {
97			return CorrectionRecord{}, &RejectError{Kind: RejectEmptyID}
98		}
99		tgt := req.Target
100		if !isFinite(tgt.X) || !isFinite(tgt.Y) || !isFinite(tgt.Heading) || !isFinite(tgt.Variance) {
101			return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
102		}
103		if tgt.Variance < 0 {
104			return CorrectionRecord{}, &RejectError{Kind: RejectNegativeVariance, Time: req.Anchor, HasTime: true}
105		}
106	
107		// 锚点必须准确命中已导入帧：trajectory[0] 是初始位姿，不能校正。
108		anchorIdx := -1
109		for j := 1; j < len(st.trajectory); j++ {
110			if st.trajectory[j].Time == req.Anchor {
111				anchorIdx = j
112				break
113			}
114		}
115		if anchorIdx < 0 {
116			return CorrectionRecord{}, &RejectError{Kind: RejectAnchorNotFound, Time: req.Anchor, HasTime: true}
117		}
118		end := len(st.trajectory) - 1
119	
120		// 受影响范围内每一帧都必须有逐帧依据（旧文件没有，不能靠推测校正）。
121		for k := anchorIdx - 1; k < len(st.sources); k++ {
122			if st.sources[k] == nil {
123				return CorrectionRecord{}, &RejectError{Kind: RejectNoBasis, Time: req.Anchor, HasTime: true}
124			}
125		}
126	
127		oldAnchor := st.trajectory[anchorIdx]
128		// 锚点到末帧的整体平移旋转规则（含只调方差的恒等情形）与打开地图时
129		// 的记录几何核对共享同一实现，见上方 poseShift。
130		shift := newPoseShift(tgt, oldAnchor)
131	
132		// ---- 在副本上推演新位姿，真实状态此时保持不变 ----
133		next := append([]Pose(nil), st.trajectory...)
134		accumVar := tgt.Variance
135		for j := anchorIdx; j <= end; j++ {
136			old := st.trajectory[j]
137			if j > anchorIdx {
138				accumVar += st.sources[j-1].moveVariance
139			}
140			x, y, heading := shift.apply(old)
141			np := Pose{
142				Time:     old.Time,
143				X:        x,
144				Y:        y,
145				Heading:  heading,
146				Variance: accumVar,
147			}
148			if !isFinite(np.X) || !isFinite(np.Y) || !isFinite(np.Heading) || !isFinite(np.Variance) {
149				return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
150			}
151			next[j] = np
152		}
153	
154		// occKey 标识某一路标的某一次出现。回环校正跨越同一路标的多次出现
155		// 时，各次出现分别聚合、分别遵守合并距离限制。观测按所在帧时间归入
156		// 当时的那次出现，时间边界规则与打开文件时的归属校验共享（见
157		// occurrence.go）；已接受观测必然属于某次出现。
158		type occKey struct {
159			id  string
160			num int
161		}
162	
163		// 受影响的路标出现：在受影响帧中被观测到的全部（标识，出现编号）。
164		affected := make(map[occKey]struct{})
165		for j := anchorIdx; j <= end; j++ {
166			t := st.trajectory[j].Time
167			for _, ob := range st.sources[j-1].observations {
168				affected[occKey{id: ob.ID, num: st.landmarks[ob.ID].occurrenceAt(t)}] = struct{}{}
169			}
170		}
171		affectedKeys := make([]occKey, 0, len(affected))
172		for k := range affected {
173			affectedKeys = append(affectedKeys, k)
174		}
175		sort.Slice(affectedKeys, func(i, j int) bool {
176			if affectedKeys[i].id != affectedKeys[j].id {
177				return affectedKeys[i].id < affectedKeys[j].id
178			}
179			return affectedKeys[i].num < affectedKeys[j].num
180		})
181	
182		// 逐“出现”运行聚合：旧文件第 1 次出现的既有观测作为固定“旧贡献”
183		// 起点（位置不随校正改变），其余观测按帧时间与同帧输入次序、以当前/
184		// 校正后位姿重放，接纳与合并规则（转换、非有限优先、首条建点、距离
185		// 判定、增量平均、计数）与导入共享同一实现（见 aggregate.go）。同一路
186		// 标的不同出现互不参与彼此的合并。
187		aggs := make(map[occKey]*observationAgg, len(affectedKeys))
188		for _, k := range affectedKeys {
189			occ := st.landmarks[k.id].appearances[k.num-1]
190			a := &observationAgg{}
191			if occ.legacyCount > 0 {
192				// 旧文件第 1 次出现：固定旧贡献作为聚合起点，不随后续校正改变。
193				a.seed(occ.legacyCount, occ.legacyMX, occ.legacyMY)
194			}
195			aggs[k] = a
196		}
197		for j := 1; j <= end; j++ {
198			src := st.sources[j-1]
199			if src == nil {
200				continue // 旧文件帧：观测已计入对应出现的 legacy 起点
201			}
202			pose := next[j]
203			t := st.trajectory[j].Time
204			for _, ob := range src.observations {
205				k := occKey{id: ob.ID, num: st.landmarks[ob.ID].occurrenceAt(t)}
206				a, ok := aggs[k]
207				if !ok {
208					continue
209				}
210				// 目标、原始观测与校正后位姿都有限，转换结果仍可能因数值过大
211				// 溢出为 NaN/无穷。与导入一致：数值异常优先于距离冲突，按
212				// non_finite 拒绝并指出该观测所在帧的实际时间、路标标识与
213				// 其所属的出现编号（不是锚点时间），无论该次出现此前是否已有
214				// 观测、记录仍有效还是已失效。
215				switch a.admit(pose, ob, st.config.MergeDistance) {
216				case obsNonFinite:
217					return CorrectionRecord{}, &RejectError{
218						Kind:          RejectNonFinite,
219						Time:          st.trajectory[j].Time,
220						HasTime:       true,
221						Landmark:      ob.ID,
222						HasLandmark:   true,
223						Occurrence:    k.num,
224						HasOccurrence: true,
225					}
226				case obsConflict:
227					return CorrectionRecord{}, &RejectError{
228						Kind:          RejectLandmarkConflict,
229						Time:          st.trajectory[j].Time,
230						HasTime:       true,
231						Landmark:      ob.ID,
232						HasLandmark:   true,
233						Occurrence:    k.num,
234						HasOccurrence: true,
235					}
236				}
237			}
238		}
239		for _, k := range affectedKeys {
240			a := aggs[k]
241			occ := st.landmarks[k.id].appearances[k.num-1]
242			if !isFinite(a.x) || !isFinite(a.y) {
243				return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
244			}
245			if a.count != occ.count {
246				// 内存不变量被破坏不可能由本包写出，按损坏处理而非半提交。
247				return CorrectionRecord{}, ErrCorrupt
248			}
249		}
250	
251		// ---- 组装校正前后快照（记录不可变） ----
252		rec := &CorrectionRecord{
253			ID:        req.ID,
254			Anchor:    req.Anchor,
255			Target:    tgt,
256			EndTime:   st.trajectory[end].Time,
257			Poses:     make([]PoseChange, 0, end-anchorIdx+1),
258			Landmarks: make([]LandmarkChange, 0, len(affectedKeys)),
259		}
260		for j := anchorIdx; j <= end; j++ {
261			rec.Poses = append(rec.Poses, PoseChange{Before: st.trajectory[j], After: next[j]})
262		}
263		for _, k := range affectedKeys {
264			occ := st.landmarks[k.id].appearances[k.num-1]
265			a := aggs[k]
266			rec.Landmarks = append(rec.Landmarks, LandmarkChange{
267				ID:         k.id,
268				Occurrence: k.num,
269				Before:     Landmark{ID: k.id, X: occ.x, Y: occ.y, Count: occ.count},
270				After:      Landmark{ID: k.id, X: a.x, Y: a.y, Count: a.count},
271			})
272		}
273	
274		// ---- 全部校验通过：暂存提交并落盘；落盘失败精确回滚 ----
275		oldTraj := append([]Pose(nil), st.trajectory...)
276		type occSnapshot struct {
277			key  occKey
278			occ  *occurrenceState
279			x, y float64
280		}
281		oldOcc := make([]occSnapshot, 0, len(affectedKeys))
282		for _, k := range affectedKeys {
283			occ := st.landmarks[k.id].appearances[k.num-1]
284			oldOcc = append(oldOcc, occSnapshot{key: k, occ: occ, x: occ.x, y: occ.y})
285		}
286		oldCorrLen := len(st.corrections)
287	
288		st.trajectory = next
289		for _, s := range oldOcc {
290			a := aggs[s.key]
291			s.occ.x, s.occ.y = a.x, a.y
292		}
293		st.corrections = append(st.corrections, rec)
294		st.corrIndex[req.ID] = canonicalCorrectionHash(req.Anchor, tgt)
295	
296		if err := m.saveReplace(); err != nil {
297			st.trajectory = oldTraj
298			for _, s := range oldOcc {
299				s.occ.x, s.occ.y = s.x, s.y
300			}
301			st.corrections = st.corrections[:oldCorrLen]
302			delete(st.corrIndex, req.ID)
303			return CorrectionRecord{}, err
304		}
305		return cloneRecord(rec), nil
306	}
307	
308	// Corrections 返回按提交次序排列的成功校正记录副本。记录一经生成永不
309	// 被后续校正改写；后续校正只是以当时最新状态为起点生成新记录。
310	func (m *Map) Corrections() ([]CorrectionRecord, error) {
311		m.mu.Lock()
312		defer m.mu.Unlock()
313		if m.closed {
314			return nil, ErrClosed
315		}
316		out := make([]CorrectionRecord, 0, len(m.state.corrections))
317		for _, rec := range m.state.corrections {
318			out = append(out, cloneRecord(rec))
319		}
320		return out, nil
321	}
322	
323	func (st *mapState) correctionRecordByID(id string) *CorrectionRecord {
324		for _, rec := range st.corrections {
325			if rec.ID == id {
326				return rec
327			}
328		}
329		return nil
330	}
331	
332	func cloneRecord(rec *CorrectionRecord) CorrectionRecord {
333		if rec == nil {
334			return CorrectionRecord{}
335		}
336		cp := *rec
337		cp.Poses = append([]PoseChange(nil), rec.Poses...)
338		cp.Landmarks = append([]LandmarkChange(nil), rec.Landmarks...)
339		return cp
340	}
341

