    replayUnknownLandmark replayRejectReason = iota // 路标没有归属边界（文件损坏）
    replayNoOccurrence                              // 观测时间不属于任何一次出现
    replayNonFinite                                 // 转换结果非有限
    replayConflict                                  // 距离超过合并上限
)

// replayReject 报告重放中第一条无法接纳的观测。
type replayReject struct {
    reason replayRejectReason
    time   int64  // 观测所在帧时间
    id     string // 路标标识
    num    int    // 归属的出现编号（未知时为 0）
}

// observationReplay 按帧时间升序、同帧按输入次序逐条重放观测：
// 每条观测先按所在帧时间归入当时的那次出现（occurrenceWindow 规则），
// 再按登记时的固定旧贡献为起点、用统一接纳规则（observationAgg）并入
// 该次出现的等权平均。
type observationReplay struct {
    mergeDistance float64
    windows       map[string][]occurrenceWindow
    aggs          map[occurrenceKey]*observationAgg
}

func newObservationReplay(mergeDistance float64) *observationReplay {
    return &observationReplay{
        mergeDistance: mergeDistance,
        windows:       make(map[string][]occurrenceWindow),
        aggs:          make(map[occurrenceKey]*observationAgg),
    }
}

// track 登记一个路标的归属边界。
func (r *observationReplay) track(id string, wins []occurrenceWindow) {
    r.windows[id] = wins
}

// seed 登记一次出现并以其固定旧观测贡献（可无）作为聚合起点；
// 只有登记过的出现才参与重建，未登记的观测被跳过。
func (r *observationReplay) seed(id string, num, legacyCount int, lx, ly float64) {
    a := &observationAgg{}
    if legacyCount > 0 {
        a.seed(legacyCount, lx, ly)
    }
    r.aggs[occurrenceKey{id: id, num: num}] = a
}

// admitFrame 重放一帧的全部观测：time 决定归属、pose 用于坐标转换，
// 观测按输入次序逐条接纳。返回第一条无法接纳的观测；全部接纳时返回 nil。
func (r *observationReplay) admitFrame(time int64, pose Pose, observations []Observation) *replayReject {
    for _, ob := range observations {
        wins, ok := r.windows[ob.ID]
        if !ok {
            return &replayReject{reason: replayUnknownLandmark, time: time, id: ob.ID}
        }
        num := occurrenceNumberAt(wins, time)
        if num == 0 {
            return &replayReject{reason: replayNoOccurrence, time: time, id: ob.ID}
        }
        a := r.aggs[occurrenceKey{id: ob.ID, num: num}]
        if a == nil {
            continue // 该次出现未登记：不参与本次重建
        }
        switch a.admit(pose, ob, r.mergeDistance) {
        case obsNonFinite:
            return &replayReject{reason: replayNonFinite, time: time, id: ob.ID, num: num}
        case obsConflict:
            return &replayReject{reason: replayConflict, time: time, id: ob.ID, num: num}
        }
    }
    return nil
}

// agg 返回某次出现重建出的聚合（计数与等权平均位置）。
func (r *observationReplay) agg(id string, num int) *observationAgg {
    return r.aggs[occurrenceKey{id: id, num: num}]
}
```

